script.setup:
// manifold-3d (WebAssembly) runs the booleans every frame: a rounded block
// minus a swarm of orbiting spheres, recomputed live and drawn as one mesh.
const BASE = "https://cdn.jsdelivr.net/npm/manifold-3d@3.5.3/";
const mod = await ctx.utils.import(BASE + "manifold.js");
const Module = mod.default ?? mod;
const wasm = await Module({ locateFile: () => BASE + "manifold.wasm" });
wasm.setup();
const { Manifold } = wasm;
const gl = ctx.gl;
const cube = Manifold.cube([2.2, 2.2, 2.2], true);
const ball = Manifold.sphere(1.55, 96);
const block = cube.intersect(ball);
cube.delete(); ball.delete();
const vao = gl.createVertexArray(), vbo = gl.createBuffer(), ibo = gl.createBuffer();
gl.bindVertexArray(vao);
gl.bindBuffer(gl.ARRAY_BUFFER, vbo);
gl.enableVertexAttribArray(0);
gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, ibo);
gl.bindVertexArray(null);
const prog = ctx.utils.createProgram(`#version 300 es
layout(location=0) in vec3 a_position; uniform mat4 u_vp, u_model; out vec3 v_w; out vec3 v_l;
void main() { v_l = a_position; vec4 w = u_model * vec4(a_position, 1.0); v_w = w.xyz; gl_Position = u_vp * w; }`, `#version 300 es
precision highp float; in vec3 v_w; in vec3 v_l; out vec4 outColor;
uniform vec3 u_eye, u_outer, u_inner;
void main() {
  // Flat normals from screen-space derivatives: the mesh changes every frame, so no normals are stored.
  vec3 n = normalize(cross(dFdx(v_w), dFdy(v_w))), v = normalize(u_eye - v_w);
  if (dot(n, v) < 0.0) n = -n;
  // Surfaces the cutters carved lie inside the block's hull: color them by depth.
  float r = max(max(abs(v_l.x), abs(v_l.y)), abs(v_l.z));
  float hull = max(step(1.095, r), step(1.538, length(v_l)));
  float depth = clamp((1.1 - min(r, length(v_l) - 0.45)) * 2.5, 0.0, 1.0);
  vec3 base = hull > 0.5 ? u_outer : mix(u_inner, u_inner * vec3(0.35, 0.3, 0.6), depth);
  vec3 l1 = normalize(vec3(0.5, 0.9, 0.4)), l2 = normalize(vec3(-0.6, -0.2, -0.7));
  float d = max(dot(n, l1), 0.0), d2 = max(dot(n, l2), 0.0);
  float sp = pow(max(dot(n, normalize(l1 + v)), 0.0), 50.0);
  vec3 c = base * (0.1 + 0.85 * d) + base * vec3(0.4, 0.6, 1.0) * d2 * 0.3 + sp * 0.45;
  outColor = vec4(pow(c, vec3(0.4545)), 1.0);
}`);
Object.assign(ctx.state, { wasm, Manifold, block, vao, vbo, ibo, prog, count: 0, cutters: [],
  camera: ctx.utils.createOrbitCamera({ distance: 7.2, theta: 0.7, phi: 1.1, fov: 35, near: 0.1, far: 50, minDistance: 2, maxDistance: 25 }) });

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, { mat4 } = ctx.utils, [w, h] = ctx.resolution;
const { Manifold } = s, t = ctx.time * u.u_speed, n = u.u_count;
const t0 = performance.now();
// Cutter spheres on tilted orbits that pass through the block's surface.
const parts = [];
for (let i = 0; i < n; i++) {
  const a = t * (0.5 + 0.13 * (i % 5)) + i * 2.399, tilt = i * 1.7;
  const R = 1.4 + 0.25 * Math.sin(t * 0.7 + i);
  const x = R * Math.cos(a), y = R * Math.sin(a) * Math.cos(tilt), z = R * Math.sin(a) * Math.sin(tilt);
  parts.push(Manifold.sphere(u.u_radius * (0.8 + 0.2 * Math.sin(i * 3.1)), 28).translate([x, y, z]));
}
const cutters = Manifold.union(parts);
const result = s.block.subtract(cutters);
const mesh = result.getMesh();
const ms = performance.now() - t0;
for (const m of parts) m.delete();
cutters.delete(); result.delete();
gl.bindVertexArray(s.vao);
gl.bindBuffer(gl.ARRAY_BUFFER, s.vbo);
gl.bufferData(gl.ARRAY_BUFFER, mesh.vertProperties, gl.DYNAMIC_DRAW);
gl.vertexAttribPointer(0, 3, gl.FLOAT, false, mesh.numProp * 4, 0);
gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, mesh.triVerts, gl.DYNAMIC_DRAW);
s.count = mesh.triVerts.length;
s.camera.update(ctx.mouse, ctx.mousePrev, ctx.mouseDown, ctx.keys, ctx.dt);
const vp = s.camera.getViewProjection(w / h);
gl.enable(gl.DEPTH_TEST);
gl.clearColor(0.045, 0.045, 0.06, 1);
gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
gl.useProgram(s.prog);
ctx.utils.setUniforms(s.prog, { u_vp: vp, u_model: mat4.fromYRotation(ctx.time * 0.15), u_eye: s.camera.getEye(), u_outer: u.u_outer, u_inner: u.u_inner });
gl.drawElements(gl.TRIANGLES, s.count, gl.UNSIGNED_INT, 0);
gl.bindVertexArray(null);
ctx.publish("boolean ms", Math.round(ms * 10) / 10);
ctx.publish("triangles", s.count / 3);
